<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { appApi, requireSession, idempotencyKey, type BrowserSession } from './api'

type Folder = 'INBOX'|'STARRED'|'SENT'|'DRAFTS'|'ARCHIVE'|'SPAM'|'TRASH'
interface Mailbox { id:string; address:string; domain:string; display_name:string; sending_enabled:boolean; receiving_enabled:boolean; counts:Record<string,number>; is_shared?:boolean; grant_count?:number; my_access_role?:string|null; unread_count?:number }
interface AccessGrant { id:string; user_id:string; role:'OWNER'|'SENDER'|'READER'; created_at?:string }
interface TeamMember { user_id:string; email:string|null; role:string }
interface MessageSummary { id:string; thread_id:string; direction:string; folder:Folder; from:string; to:string[]; subject:string; preview:string; is_read:boolean; is_starred:boolean; delivery_status?:string; has_attachments:boolean; occurred_at:string }
interface MessageDetail extends MessageSummary { cc:string[]; bcc:string[]; reply_to?:string; text:string; html?:string; attachments:Array<{id:string;filename:string;content_type:string;size:number;download_url:string}>; message_id?:string; in_reply_to?:string; reply_to_message_id?:string; references:string[] }

const folders:Array<{id:Folder;label:string;icon:string}>=[
  {id:'INBOX',label:'Inbox',icon:'▰'},{id:'STARRED',label:'Starred',icon:'☆'},
  {id:'SENT',label:'Sent',icon:'↗'},{id:'DRAFTS',label:'Drafts',icon:'□'},
  {id:'ARCHIVE',label:'Archive',icon:'▣'},{id:'SPAM',label:'Spam',icon:'!'},
  {id:'TRASH',label:'Trash',icon:'⌫'},
]
const session=ref<BrowserSession>({authenticated:false})
const mailboxes=ref<Mailbox[]>([]),selectedMailboxId=ref(''),folder=ref<Folder>('INBOX')
const messages=ref<MessageSummary[]>([]),selected=ref<MessageDetail|null>(null)
const loading=ref(true),listLoading=ref(false),error=ref(''),notice=ref(''),query=ref('')
const composeOpen=ref(false),sending=ref(false),composeTo=ref(''),composeSubject=ref(''),composeText=ref(''),replyToId=ref<string|undefined>(),draftId=ref<string|undefined>()
const composeSendKey=ref('')
const accessOpen=ref(false),accessLoading=ref(false),accessError=ref('')
const accessGrants=ref<AccessGrant[]>([]),teamMembers=ref<TeamMember[]>([]),grantUserId=ref(''),grantRole=ref<'OWNER'|'SENDER'|'READER'>('READER')
const selectedMailbox=computed(()=>mailboxes.value.find(item=>item.id===selectedMailboxId.value)||null)
const groupedMailboxes=computed(()=>mailboxes.value.reduce<Record<string,Mailbox[]>>((groups,mailbox)=>{(groups[mailbox.domain]||=[]).push(mailbox);return groups},{}))
const canManage=computed(()=>['OWNER','ADMIN','platform_admin','tenant_admin'].includes(session.value.role||''))
const activeCount=computed(()=>selectedMailbox.value?.counts[folder.value]||0)
const pendingReceive=computed(()=>mailboxes.value.filter(item=>!item.receiving_enabled).length)

async function loadMailboxes(selectFirst=true){mailboxes.value=await appApi<Mailbox[]>('/app/api/mailboxes');if(selectFirst&&!selectedMailboxId.value&&mailboxes.value.length)selectedMailboxId.value=mailboxes.value[0].id}
async function loadMessages(){
  if(!selectedMailboxId.value){messages.value=[];selected.value=null;return}listLoading.value=true;error.value=''
  try{const result=await appApi<{items:MessageSummary[]}>(`/app/api/mailboxes/${selectedMailboxId.value}/messages?folder=${folder.value}&q=${encodeURIComponent(query.value)}`);messages.value=result.items;if(selected.value&&!messages.value.some(item=>item.id===selected.value?.id))selected.value=null}
  catch(err){error.value=err instanceof Error?err.message:'mailbox_unavailable'}finally{listLoading.value=false}
}
async function boot(){loading.value=true;try{session.value=await requireSession();await loadMailboxes();await loadMessages()}catch(err){error.value=err instanceof Error?err.message:'webmail_unavailable'}finally{loading.value=false}}
async function syncMailboxes(){try{const result=await appApi<{created:number;send_ready:number;pending_send:number;receive_ready:number;pending_receive:number}>('/app/api/mailboxes/sync',{method:'POST'});notice.value=`${result.created} mailboxes added · ${result.send_ready} ready to send · ${result.receive_ready} ready to receive · ${result.pending_receive} awaiting inbound DNS/routes`;await loadMailboxes();await loadMessages()}catch(err){error.value=err instanceof Error?err.message:'mailbox_sync_failed'}}
async function activateInboxes(){try{const result=await appApi<{activated_domains:number;activated_routes:number}>('/app/api/mailboxes/inbound/activate',{method:'POST'});notice.value=`Inbound activated for ${result.activated_domains} domains and ${result.activated_routes} exact routes`;await loadMailboxes(false);await loadMessages()}catch(err){error.value=err instanceof Error?err.message:'inbound_activation_failed'}}
async function chooseMailbox(id:string){selectedMailboxId.value=id;selected.value=null;await loadMessages()}
async function chooseFolder(id:Folder){folder.value=id;selected.value=null;await loadMessages()}
async function openMessage(item:MessageSummary){selected.value=await appApi<MessageDetail>(`/app/api/mailboxes/${selectedMailboxId.value}/messages/${item.id}`);if(!item.is_read){await patchMessage(item.id,{is_read:true},false);item.is_read=true}}
async function patchMessage(id:string,patch:Record<string,unknown>,refresh=true){const updated=await appApi<MessageDetail>(`/app/api/mailboxes/${selectedMailboxId.value}/messages/${id}`,{method:'PATCH',body:JSON.stringify(patch)});if(selected.value?.id===id)selected.value=updated;if(refresh){await loadMailboxes(false);await loadMessages()}}
async function moveSelected(destination:Folder){if(!selected.value)return;await patchMessage(selected.value.id,{folder:destination});selected.value=null}
async function deleteSelected(permanent=false){if(!selected.value)return;await appApi(`/app/api/mailboxes/${selectedMailboxId.value}/messages/${selected.value.id}${permanent?'?permanent=true':''}`,{method:'DELETE'});selected.value=null;await loadMailboxes(false);await loadMessages()}
function beginCompose(){composeSendKey.value=idempotencyKey('webmail-send');composeOpen.value=true}
function newMessage(){composeTo.value='';composeSubject.value='';composeText.value='';replyToId.value=undefined;draftId.value=undefined;beginCompose()}
function reply(){if(!selected.value)return;composeTo.value=selected.value.direction==='INBOUND'?selected.value.from:selected.value.to[0]||'';composeSubject.value=/^re:/i.test(selected.value.subject)?selected.value.subject:`Re: ${selected.value.subject}`;composeText.value='';replyToId.value=selected.value.id;draftId.value=undefined;beginCompose()}
function editDraft(){if(!selected.value||selected.value.folder!=='DRAFTS')return;composeTo.value=selected.value.to[0]||'';composeSubject.value=selected.value.subject;composeText.value=selected.value.text;replyToId.value=selected.value.reply_to_message_id;draftId.value=selected.value.id;beginCompose()}
async function saveDraft(){if(!selectedMailbox.value?.sending_enabled)return;const body=JSON.stringify({to:composeTo.value||null,subject:composeSubject.value,text:composeText.value,reply_to_message_id:replyToId.value});const path=draftId.value?`/app/api/mailboxes/${selectedMailboxId.value}/drafts/${draftId.value}`:`/app/api/mailboxes/${selectedMailboxId.value}/drafts`;const draft=await appApi<MessageDetail>(path,{method:draftId.value?'PUT':'POST',body});draftId.value=draft.id;notice.value='Draft saved';await loadMailboxes(false)}
async function send(){sending.value=true;notice.value='';error.value='';if(!composeSendKey.value)composeSendKey.value=idempotencyKey('webmail-send');try{await appApi(`/app/api/mailboxes/${selectedMailboxId.value}/send`,{method:'POST',headers:{'Idempotency-Key':composeSendKey.value},body:JSON.stringify({to:composeTo.value,subject:composeSubject.value,text:composeText.value,draft_id:draftId.value,reply_to_message_id:replyToId.value})});composeOpen.value=false;composeSendKey.value='';notice.value='Message accepted for delivery';folder.value='SENT';await loadMailboxes(false);await loadMessages()}catch(err){error.value=err instanceof Error?err.message:'send_failed'}finally{sending.value=false}}
async function loadAccess(){if(!selectedMailboxId.value)return;accessLoading.value=true;accessError.value='';try{const [grants,members]=await Promise.all([appApi<AccessGrant[]>(`/app/api/mailboxes/${selectedMailboxId.value}/access`),appApi<TeamMember[]>('/app/api/team')]);accessGrants.value=grants;teamMembers.value=members;if(!grantUserId.value){const candidate=members.find(member=>!grants.some(grant=>grant.user_id===member.user_id));grantUserId.value=candidate?.user_id||''}}catch(err){accessError.value=err instanceof Error?err.message:'mailbox_access_unavailable'}finally{accessLoading.value=false}}
async function openAccess(){accessOpen.value=true;grantUserId.value='';grantRole.value='READER';await loadAccess()}
async function grantAccess(){if(!grantUserId.value||!selectedMailboxId.value)return;accessError.value='';try{await appApi(`/app/api/mailboxes/${selectedMailboxId.value}/access`,{method:'POST',body:JSON.stringify({user_id:grantUserId.value,role:grantRole.value})});notice.value='Mailbox access updated';grantUserId.value='';await loadAccess();await loadMailboxes(false)}catch(err){accessError.value=err instanceof Error?err.message:'mailbox_access_update_failed'}}
async function revokeAccess(userId:string){if(!selectedMailboxId.value)return;accessError.value='';try{await appApi(`/app/api/mailboxes/${selectedMailboxId.value}/access/${encodeURIComponent(userId)}`,{method:'DELETE'});notice.value='Mailbox access removed';await loadAccess();await loadMailboxes(false)}catch(err){accessError.value=err instanceof Error?err.message:'mailbox_access_revoke_failed'}}
function memberLabel(userId:string){const member=teamMembers.value.find(item=>item.user_id===userId);return member?.email||userId}
async function logout(){const result=await appApi<{end_session_url?:string}>('/auth/logout',{method:'POST'});location.assign(result.end_session_url||'/logged-out')}
watch([composeTo,composeSubject,composeText,replyToId,draftId],()=>{if(composeOpen.value&&!sending.value)composeSendKey.value=idempotencyKey('webmail-send')})
let searchTimer=0;watch(query,()=>{window.clearTimeout(searchTimer);searchTimer=window.setTimeout(loadMessages,250)});onMounted(boot)
</script>

<template>
  <div class="mail-shell">
    <header class="topbar"><a class="brand" href="/app"><span>K</span><strong>Klyrow Mail</strong></a><label class="search"><span aria-hidden="true">⌕</span><input v-model="query" type="search" placeholder="Search this mailbox" aria-label="Search mail"></label><nav><a href="/app">Command center</a><button @click="logout">Sign out</button></nav></header>
    <div v-if="loading" class="full-state" role="status">Opening your mailboxes…</div>
    <div v-else-if="error&&!mailboxes.length" class="full-state error" role="alert">{{ error }} <button @click="boot">Try again</button></div>
    <main v-else class="mail-grid">
      <aside class="mail-nav">
        <button class="compose-button" :disabled="!selectedMailbox?.sending_enabled" @click="newMessage"><span>＋</span> Compose</button>
        <div v-if="mailboxes.length" class="mailbox-picker"><p class="nav-label">MAILBOXES</p><details v-for="(items,domain) in groupedMailboxes" :key="domain" open><summary>{{ domain }} <small>{{ items.length }}</small></summary><button v-for="mailbox in items" :key="mailbox.id" :class="{active:selectedMailboxId===mailbox.id}" @click="chooseMailbox(mailbox.id)"><span class="avatar">{{ mailbox.address[0].toUpperCase() }}</span><span><strong>{{ mailbox.display_name }}</strong><small>{{ mailbox.address }} · {{ mailbox.grant_count ? mailbox.grant_count + ' shared' : 'private' }}</small></span><b v-if="mailbox.counts.UNREAD">{{ mailbox.counts.UNREAD }}</b></button></details></div>
        <div v-if="selectedMailbox" class="folder-nav"><p class="nav-label">FOLDERS</p><button v-for="item in folders" :key="item.id" :class="{active:folder===item.id}" @click="chooseFolder(item.id)"><span>{{ item.icon }}</span>{{ item.label }}<b v-if="selectedMailbox.counts[item.id]">{{ selectedMailbox.counts[item.id] }}</b></button></div>
        <div class="account-card" v-if="selectedMailbox"><span :class="['receive-dot',{ready:selectedMailbox.receiving_enabled}]"></span><p><strong>{{ selectedMailbox.receiving_enabled?'Send & receive ready':'Sending ready' }}</strong><small>{{ selectedMailbox.receiving_enabled?'Inbound route active':'Inbound DNS or route pending' }}</small><small>Access: {{ selectedMailbox.my_access_role || 'read' }} · {{ selectedMailbox.grant_count || 0 }} explicit grants</small></p></div>
        <button v-if="canManage&&pendingReceive" class="inbound-button" @click="activateInboxes">Activate {{ pendingReceive }} inboxes</button><button v-if="canManage&&selectedMailbox" class="share-button" @click="openAccess">Manage mailbox access</button>
      </aside>
      <section v-if="!mailboxes.length" class="empty-workspace"><div class="empty-icon">✉</div><h1>Your mail suite is ready to provision</h1><p>Turn every verified sender into a secure Klyrow mailbox. Existing inbound destinations stay intact.</p><button v-if="canManage" class="primary" @click="syncMailboxes">Provision verified senders</button><p v-else>Ask a workspace owner to provision and assign a mailbox.</p></section>
      <template v-else>
        <section class="message-list" aria-label="Message list"><header><div><p>{{ selectedMailbox?.address }}</p><h1>{{ folders.find(item=>item.id===folder)?.label }} <small>{{ activeCount }}</small></h1></div><button class="icon-button" title="Refresh" @click="loadMessages">↻</button></header><p v-if="notice" class="notice" role="status">{{ notice }}</p><p v-if="error" class="notice error" role="alert">{{ error }}</p><div v-if="listLoading" class="list-state">Loading messages…</div><button v-for="item in messages" v-else :key="item.id" :class="['message-row',{unread:!item.is_read,active:selected?.id===item.id}]" @click="openMessage(item)"><span class="sender-avatar">{{ (item.direction==='INBOUND'?item.from:(item.to[0]||'?'))[0]?.toUpperCase() }}</span><span class="row-copy"><span class="row-line"><strong>{{ item.direction==='INBOUND'?item.from:item.to.join(', ') }}</strong><time>{{ new Date(item.occurred_at).toLocaleDateString(undefined,{month:'short',day:'numeric'}) }}</time></span><span class="subject">{{ item.subject||'(no subject)' }}</span><span class="preview">{{ item.preview||'No text preview' }}</span></span><span class="row-flags"><span v-if="item.has_attachments">⌕</span><span v-if="item.is_starred" class="gold">★</span></span></button><div v-if="!listLoading&&!messages.length" class="list-state"><span>✓</span><strong>No messages here</strong><small>{{ query?'Try another search.':'This folder is clear.' }}</small></div></section>
        <section class="reader" aria-live="polite"><div v-if="!selected" class="reader-empty"><span>✉</span><h2>Select a message</h2><p>Choose a conversation from the list to read it here.</p></div><template v-else><header class="reader-actions"><button v-if="selected.folder==='DRAFTS'" @click="editDraft">✎ Edit draft</button><button v-else @click="reply">↩ Reply</button><button @click="patchMessage(selected.id,{is_starred:!selected.is_starred})">{{ selected.is_starred?'★':'☆' }} Star</button><button v-if="selected.folder!=='ARCHIVE'&&selected.folder!=='DRAFTS'" @click="moveSelected('ARCHIVE')">Archive</button><button v-if="selected.folder!=='TRASH'" @click="deleteSelected(false)">Trash</button><button v-else class="danger" @click="deleteSelected(true)">Delete forever</button></header><article class="message-content"><p class="eyebrow">{{ selected.direction }} · {{ selected.delivery_status||'stored' }}</p><h2>{{ selected.subject||'(no subject)' }}</h2><div class="address-block"><span class="large-avatar">{{ selected.from[0]?.toUpperCase() }}</span><p><strong>{{ selected.from }}</strong><small>to {{ selected.to.join(', ')||selectedMailbox?.address }}</small></p><time>{{ new Date(selected.occurred_at).toLocaleString() }}</time></div><div class="body-text">{{ selected.text||'This message contains no plain-text body.' }}</div><div v-if="selected.attachments.length" class="attachments"><p>Attachments</p><a v-for="file in selected.attachments" :key="file.id" :href="file.download_url" download><span>▤</span><div><strong>{{ file.filename }}</strong><small>{{ file.content_type }} · {{ Math.ceil(file.size/1024) }} KB</small></div></a></div></article></template></section>
      </template>
    </main>
    <div v-if="accessOpen" class="compose-layer" @click.self="accessOpen=false"><section class="access-window" role="dialog" aria-modal="true" aria-labelledby="access-title"><header><div><p>SHARED MAILBOX</p><h2 id="access-title">Access to {{ selectedMailbox?.address }}</h2></div><button aria-label="Close access manager" @click="accessOpen=false">×</button></header><div class="access-body"><p v-if="accessError" class="notice error" role="alert">{{ accessError }}</p><div v-if="accessLoading" class="list-state">Loading access…</div><template v-else><form class="grant-form" @submit.prevent="grantAccess"><label><span>Workspace member</span><select v-model="grantUserId" required><option value="" disabled>Select a member</option><option v-for="member in teamMembers" :key="member.user_id" :value="member.user_id">{{ member.email || member.user_id }} · {{ member.role }}</option></select></label><label><span>Mailbox role</span><select v-model="grantRole"><option value="READER">Reader</option><option value="SENDER">Sender</option><option value="OWNER">Owner</option></select></label><button class="primary" :disabled="!grantUserId">Grant / update access</button></form><div class="grant-list"><p class="nav-label">EXPLICIT GRANTS</p><div v-if="!accessGrants.length" class="list-state">No explicit mailbox grants. Tenant managers retain management access.</div><article v-for="grant in accessGrants" :key="grant.id"><div><strong>{{ memberLabel(grant.user_id) }}</strong><small>{{ grant.role }}</small></div><button class="danger" @click="revokeAccess(grant.user_id)">Revoke</button></article></div></template></div></section></div>
    <div v-if="composeOpen" class="compose-layer" @click.self="composeOpen=false"><section class="compose-window" role="dialog" aria-modal="true" aria-labelledby="compose-title"><header><h2 id="compose-title">{{ replyToId?'Reply':'New message' }}</h2><button aria-label="Close composer" @click="composeOpen=false">×</button></header><form @submit.prevent="send"><div class="from-line"><span>From</span><strong>{{ selectedMailbox?.address }}</strong></div><label><span>To</span><input v-model="composeTo" type="email" required autocomplete="off" autofocus></label><label><span>Subject</span><input v-model="composeSubject" maxlength="998" placeholder="Subject"></label><textarea v-model="composeText" required rows="13" placeholder="Write your message…"></textarea><footer><button class="send-button" :disabled="sending">{{ sending?'Sending…':'Send' }} <span>↗</span></button><button type="button" class="draft-button" @click="saveDraft">Save draft</button><button type="button" class="discard" @click="composeOpen=false">Discard</button></footer></form></section></div>
  </div>
</template>

<style scoped>
*{box-sizing:border-box}.mail-shell{min-height:100vh;background:#080808;color:#f5f5f4;font-family:Inter,"Helvetica Neue",Arial,sans-serif}.topbar{height:66px;display:grid;grid-template-columns:270px minmax(260px,640px) 1fr;gap:28px;align-items:center;padding:0 22px;border-bottom:1px solid #272727;background:#050505}.brand{display:flex;align-items:center;gap:10px;color:#fff;text-decoration:none}.brand>span{display:grid;place-items:center;width:34px;height:34px;border-radius:5px;background:#ffd700;color:#080808;font-weight:900}.search{height:40px;display:flex;align-items:center;gap:10px;padding:0 13px;border:1px solid #333;background:#111;border-radius:6px;color:#8b8b89}.search input{width:100%;border:0;outline:0;background:transparent;color:#fff;font:inherit}.topbar nav{justify-self:end;display:flex;gap:16px}.topbar nav a,.topbar nav button{color:#aaa;text-decoration:none;border:0;background:transparent;font:inherit;cursor:pointer}.mail-grid{height:calc(100vh - 66px);display:grid;grid-template-columns:270px minmax(330px,410px) minmax(420px,1fr)}.mail-nav{border-right:1px solid #262626;background:#070707;padding:18px 14px;overflow:auto}.compose-button{width:100%;height:48px;border:0;border-radius:5px;background:#ffd700;color:#080808;font-weight:850;cursor:pointer;margin-bottom:22px}.compose-button span{font-size:20px}.compose-button:disabled{opacity:.45}.nav-label{font-size:10px;color:#71716f;letter-spacing:.15em;font-weight:800;margin:18px 10px 8px}.mailbox-picker summary{list-style:none;cursor:pointer;color:#aaa;padding:8px 9px;font-size:12px;font-weight:750}.mailbox-picker summary small{float:right;color:#666}.mailbox-picker button{width:100%;display:grid;grid-template-columns:31px 1fr auto;align-items:center;gap:9px;padding:8px;border:0;border-radius:4px;background:transparent;color:#ddd;text-align:left;cursor:pointer}.mailbox-picker button:hover,.mailbox-picker button.active,.folder-nav button:hover,.folder-nav button.active{background:#181818;color:#fff}.avatar,.sender-avatar,.large-avatar{display:grid;place-items:center;border-radius:50%;background:#292929;color:#ffd700;font-weight:800}.avatar{width:29px;height:29px;font-size:12px}.mailbox-picker strong,.mailbox-picker small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.mailbox-picker strong{font-size:12px}.mailbox-picker small{font-size:10px;color:#777}.mailbox-picker b,.folder-nav b{font-size:10px;background:#ffd700;color:#080808;padding:2px 5px;border-radius:10px}.folder-nav{border-top:1px solid #222;margin-top:14px}.folder-nav button{width:100%;height:37px;border:0;border-radius:4px;background:transparent;color:#92928f;text-align:left;padding:0 10px;display:grid;grid-template-columns:24px 1fr auto;align-items:center;cursor:pointer}.folder-nav button.active span{color:#ffd700}.account-card{display:flex;gap:9px;padding:14px 10px;margin-top:20px;border-top:1px solid #222}.receive-dot{width:8px;height:8px;border-radius:50%;background:#d29b2d;margin-top:4px}.receive-dot.ready{background:#43d17b}.account-card p{margin:0}.account-card strong,.account-card small{display:block;font-size:10px}.account-card small{color:#70706e;margin-top:3px}.message-list{border-right:1px solid #292929;overflow:auto;background:#0c0c0c}.message-list>header{height:86px;position:sticky;top:0;z-index:2;display:flex;align-items:center;justify-content:space-between;padding:16px 18px;border-bottom:1px solid #292929;background:#0c0c0cf2}.message-list header p{font-size:11px;color:#7e7e7b;margin:0 0 5px}.message-list h1{font-size:21px;margin:0}.message-list h1 small{font-size:11px;color:#777}.icon-button{width:34px;height:34px;border:1px solid #333;border-radius:4px;background:#141414;color:#bbb;cursor:pointer}.message-row{width:100%;min-height:110px;border:0;border-bottom:1px solid #222;background:#0c0c0c;color:#ccc;padding:16px;display:grid;grid-template-columns:36px 1fr 20px;gap:11px;text-align:left;cursor:pointer}.message-row:hover,.message-row.active{background:#151515}.me